import { useState } from "react";

type Task = { id: string; title: string; done: boolean };

export function TaskList({ initial }: { initial: Task[] }) {
  const [tasks, setTasks] = useState(initial);

  function addTask(title: string) {
    tasks.push({ id: crypto.randomUUID(), title, done: false });
    setTasks(tasks); // same array: Object.is sees no change
  }

  function toggle(task: Task) {
    task.done = !task.done; // edits an object the last render showed
    setTasks([...tasks]); // new array, same old task objects
  }

  return <TaskView tasks={tasks} onAdd={addTask} onToggle={toggle} />;
}

import { useState } from "react";

type Task = { id: string; title: string; done: boolean };

export function TaskList({ initial }: { initial: Task[] }) {
  // readonly: TypeScript now rejects push, splice and sort on tasks
  const [tasks, setTasks] = useState<readonly Task[]>(initial);

  function addTask(title: string) {
    setTasks([...tasks, { id: crypto.randomUUID(), title, done: false }]);
  }

  function toggle(task: Task) {
    // A new array, and a new object only for the task that changed
    setTasks(tasks.map((t) => (t.id === task.id ? { ...t, done: !t.done } : t)));
  }

  return <TaskView tasks={tasks} onAdd={addTask} onToggle={toggle} />;
}

